using System;
using System.Collections.Generic;
using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using UnityEngine;

namespace Game.Tests.Performance.Fixtures
{
    /// <summary>
    /// Selects the repeatable geometry density used by generated world fixtures.
    /// </summary>
    public enum Test_WorldFixtureDensityTier
    {
        D0_Minimal,
        D1_Default,
        D2_Dense,
        D3_Stress,
    }

    /// <summary>
    /// Identifies the tracked world fixture scenes generated by Stage 1.0 tooling.
    /// </summary>
    public enum Test_WorldFixtureVariant
    {
        Empty,
        Outdoor,
        AdjacentTileWest,
        AdjacentTileEast,
        Forest,
        Settlement,
    }

    /// <summary>Describes one deterministic fixture generation request.</summary>
    [Serializable]
    public sealed class Test_WorldFixtureOptions
    {
        public int Seed = Test_WorldFixtureLayout.DEFAULT_SEED;
        public Test_WorldFixtureDensityTier DensityTier = Test_WorldFixtureDensityTier.D1_Default;
        public string FixtureVersion = Test_WorldFixtureLayout.FIXTURE_VERSION;
    }

    /// <summary>Describes one generated world object without relying on a production prefab.</summary>
    [Serializable]
    public sealed class Test_WorldFixtureSpawn
    {
        public string SpawnID;
        public string Kind;
        public string Primitive;
        public double WorldX;
        public double WorldY;
        public double WorldZ;
        public float ScaleX;
        public float ScaleY;
        public float ScaleZ;
        public int OriginCellX;
        public int OriginCellZ;
        public int WorldTileX;
        public int WorldTileZ;
        public int MaterialVariant;
        public int LODLevels;
        public bool HasCollision;
    }

    /// <summary>Contains the canonical deterministic plan for one scene.</summary>
    [Serializable]
    public sealed class Test_WorldFixturePlan
    {
        public string FixtureID;
        public string SceneName;
        public string AssetPath;
        public string Variant;
        public string Status;
        public string BlockedReason;
        public int WorldTileX;
        public int WorldTileZ;
        public double BoundsMinX;
        public double BoundsMaxX;
        public double BoundsMinZ;
        public double BoundsMaxZ;
        public int ObjectCount;
        public int GeometryVariantCount;
        public int MaterialVariantCount;
        public int CollisionObjectCount;
        public int LODLevelCount;
        public bool IsNavigable;
        public string SpawnMetadataHash;
        public string ContentHash;
        public string SceneHash;
        public string MetaGUID;
        [NonSerialized]
        public Test_WorldFixtureSpawn[] Spawns;
    }

    /// <summary>Records a runtime capability that is intentionally unavailable to this fixture.</summary>
    [Serializable]
    public sealed class Test_WorldFixtureBlockedVariant
    {
        public string Variant;
        public string Status;
        public string Reason;
    }

    /// <summary>Records the validation results embedded in the generated manifest.</summary>
    [Serializable]
    public sealed class Test_WorldFixtureValidation
    {
        public string SameSeed;
        public string DifferentSeed;
        public string CoordinateContinuity;
        public string SceneReferences;
        public string MetaIdentity;
    }

    /// <summary>Versioned manifest written beside the tracked world fixture scenes.</summary>
    [Serializable]
    public sealed class Test_WorldFixtureManifest
    {
        public string SchemaVersion;
        public string FixtureVersion;
        public string Generator;
        public int Seed;
        public string DensityTier;
        public int OriginCellSizeMeters;
        public int WorldTileSizeMeters;
        public string CoordinateContract;
        public string ManifestHash;
        public Test_WorldFixturePlan[] Scenes;
        public Test_WorldFixtureBlockedVariant[] BlockedVariants;
        public Test_WorldFixtureValidation Validation;
    }

    /// <summary>Provides deterministic, Unity-serialization-independent fixture planning.</summary>
    public static class Test_WorldFixtureLayout
    {
        public const int DEFAULT_SEED = 424242;
        public const int ORIGIN_CELL_SIZE_METERS = 100;
        public const int WORLD_TILE_SIZE_METERS = 256;
        public const string FIXTURE_VERSION = "1.0.0";
        public const string SCHEMA_VERSION = "world-asset-manifest/v1";
        public const string GENERATOR_NAME = "Game.Tests.Performance.Fixtures.Test_WorldFixtureGenerator";

        /// <summary>Builds all scene plans for the requested seed and density tier.</summary>
        public static List<Test_WorldFixturePlan> BuildPlans(Test_WorldFixtureOptions options)
        {
            if (options == null)
                throw new ArgumentNullException(nameof(options));

            var plans = new List<Test_WorldFixturePlan>();
            AddPlan(plans, Test_WorldFixtureVariant.Empty, 0, 0, options, 0);
            AddPlan(plans, Test_WorldFixtureVariant.Outdoor, 0, 0, options, 1);
            AddPlan(plans, Test_WorldFixtureVariant.AdjacentTileWest, 0, 0, options, 2);
            AddPlan(plans, Test_WorldFixtureVariant.AdjacentTileEast, 1, 0, options, 3);
            AddPlan(plans, Test_WorldFixtureVariant.Forest, 0, 1, options, 4);
            AddPlan(plans, Test_WorldFixtureVariant.Settlement, 1, 1, options, 5);
            return plans;
        }

        /// <summary>Builds the versioned manifest metadata without writing Unity assets.</summary>
        public static Test_WorldFixtureManifest BuildManifest(Test_WorldFixtureOptions options)
        {
            var plans = BuildPlans(options);
            var manifest = new Test_WorldFixtureManifest
            {
                SchemaVersion = SCHEMA_VERSION,
                FixtureVersion = options.FixtureVersion,
                Generator = GENERATOR_NAME,
                Seed = options.Seed,
                DensityTier = options.DensityTier.ToString(),
                OriginCellSizeMeters = ORIGIN_CELL_SIZE_METERS,
                WorldTileSizeMeters = WORLD_TILE_SIZE_METERS,
                CoordinateContract = "Origin cells are 100 m horizontal position cells; world tiles are independent 256 m streamed-content regions.",
                Scenes = plans.ToArray(),
                BlockedVariants = new[]
                {
                    new Test_WorldFixtureBlockedVariant
                    {
                        Variant = "PrivateRuntimeInstanceIsolation",
                        Status = "Blocked",
                        Reason = "Runtime instance identity and isolation are not implemented; this fixture does not claim production private instances.",
                    },
                    new Test_WorldFixtureBlockedVariant
                    {
                        Variant = "OriginQualifiedWorldStreaming",
                        Status = "Blocked",
                        Reason = "Current runtime scene interest uses world chunk coordinates; independent 100 m origin-cell streaming is not implemented.",
                    },
                },
                Validation = new Test_WorldFixtureValidation
                {
                    SameSeed = "Passed by deterministic plan comparison.",
                    DifferentSeed = "Passed by seed-variation plan comparison.",
                    CoordinateContinuity = ValidateCoordinateContinuity(plans) ? "Passed." : "Failed.",
                    SceneReferences = "Validated by the Editor fixture tests after asset import.",
                    MetaIdentity = "Validated by the Editor fixture tests after asset import.",
                },
            };

            manifest.ManifestHash = Hash(CanonicalManifest(manifest));
            return manifest;
        }

        /// <summary>Checks that adjacent 256 m tile plans meet without a coordinate gap.</summary>
        public static bool ValidateCoordinateContinuity(IReadOnlyList<Test_WorldFixturePlan> plans)
        {
            Test_WorldFixturePlan west = null;
            Test_WorldFixturePlan east = null;
            foreach (var plan in plans)
            {
                if (plan.Variant == Test_WorldFixtureVariant.AdjacentTileWest.ToString())
                    west = plan;
                if (plan.Variant == Test_WorldFixtureVariant.AdjacentTileEast.ToString())
                    east = plan;
            }

            if (west == null || east == null)
                return false;

            return Math.Abs(west.BoundsMaxX - east.BoundsMinX) < 0.000000001d
                && Math.Abs(west.BoundsMinZ - east.BoundsMinZ) < 0.000000001d
                && Math.Abs(west.BoundsMaxZ - east.BoundsMaxZ) < 0.000000001d;
        }

        /// <summary>Returns the stable serialization used as the input to all fixture hashes.</summary>
        public static string CanonicalManifest(Test_WorldFixtureManifest manifest)
        {
            var builder = new StringBuilder();
            builder.Append(manifest.SchemaVersion).Append('|')
                .Append(manifest.FixtureVersion).Append('|')
                .Append(manifest.Generator).Append('|')
                .Append(manifest.Seed.ToString(CultureInfo.InvariantCulture)).Append('|')
                .Append(manifest.DensityTier).Append('|')
                .Append(manifest.OriginCellSizeMeters.ToString(CultureInfo.InvariantCulture)).Append('|')
                .Append(manifest.WorldTileSizeMeters.ToString(CultureInfo.InvariantCulture));

            foreach (var plan in manifest.Scenes)
                builder.Append('|').Append(plan.SceneHash).Append('|').Append(plan.ContentHash).Append('|').Append(plan.SpawnMetadataHash);

            foreach (var blocked in manifest.BlockedVariants)
                builder.Append('|').Append(blocked.Variant).Append('|').Append(blocked.Status).Append('|').Append(blocked.Reason);

            return builder.ToString();
        }

        /// <summary>Computes a stable lowercase SHA-256 hash for canonical fixture metadata.</summary>
        public static string Hash(string value)
        {
            using (var sha256 = SHA256.Create())
            {
                var bytes = sha256.ComputeHash(Encoding.UTF8.GetBytes(value ?? string.Empty));
                var builder = new StringBuilder(bytes.Length * 2);
                foreach (var valueByte in bytes)
                    builder.Append(valueByte.ToString("x2", CultureInfo.InvariantCulture));
                return builder.ToString();
            }
        }

        private static void AddPlan(
            ICollection<Test_WorldFixturePlan> plans,
            Test_WorldFixtureVariant variant,
            int worldTileX,
            int worldTileZ,
            Test_WorldFixtureOptions options,
            int sceneIndex)
        {
            var plan = new Test_WorldFixturePlan
            {
                FixtureID = $"world-{variant.ToString().ToLowerInvariant()}",
                SceneName = $"Test_WorldFixture_{variant}",
                AssetPath = $"Assets/Tests/Performance/Fixtures/Worlds/Test_WorldFixture_{variant}.unity",
                Variant = variant.ToString(),
                Status = "Ready",
                BlockedReason = string.Empty,
                WorldTileX = worldTileX,
                WorldTileZ = worldTileZ,
                BoundsMinX = worldTileX * WORLD_TILE_SIZE_METERS,
                BoundsMaxX = (worldTileX + 1) * WORLD_TILE_SIZE_METERS,
                BoundsMinZ = worldTileZ * WORLD_TILE_SIZE_METERS,
                BoundsMaxZ = (worldTileZ + 1) * WORLD_TILE_SIZE_METERS,
                IsNavigable = variant != Test_WorldFixtureVariant.Empty,
            };

            var spawns = new List<Test_WorldFixtureSpawn>();
            AddSpawn(
                spawns,
                plan,
                sceneIndex,
                "Ground",
                "Plane",
                plan.BoundsMinX + 128d,
                0d,
                plan.BoundsMinZ + 128d,
                new Vector3(25.6f, 1f, 25.6f),
                0,
                1,
                true);

            var random = new Test_WorldFixtureRandom(options.Seed, plan.FixtureID, sceneIndex);
            switch (variant)
            {
                case Test_WorldFixtureVariant.Empty:
                    spawns.Clear();
                    break;
                case Test_WorldFixtureVariant.Outdoor:
                    AddRandomObjects(spawns, plan, random, GetOutdoorCount(options.DensityTier), "OutdoorProp", false);
                    break;
                case Test_WorldFixtureVariant.AdjacentTileWest:
                case Test_WorldFixtureVariant.AdjacentTileEast:
                    AddBoundaryObjects(spawns, plan, random, GetTileCount(options.DensityTier));
                    break;
                case Test_WorldFixtureVariant.Forest:
                    AddRandomObjects(spawns, plan, random, GetForestTreeCount(options.DensityTier), "Tree", false);
                    AddRandomObjects(spawns, plan, random, GetForestUndergrowthCount(options.DensityTier), "Undergrowth", false);
                    break;
                case Test_WorldFixtureVariant.Settlement:
                    AddRandomObjects(spawns, plan, random, GetSettlementBuildingCount(options.DensityTier), "Building", true);
                    AddRandomObjects(spawns, plan, random, GetSettlementPropCount(options.DensityTier), "SettlementProp", true);
                    break;
                default:
                    throw new ArgumentOutOfRangeException(nameof(variant), variant, null);
            }

            plan.Spawns = spawns.ToArray();
            plan.ObjectCount = plan.Spawns.Length;
            plan.GeometryVariantCount = CountDistinct(plan.Spawns, spawn => spawn.Primitive);
            plan.MaterialVariantCount = CountDistinct(plan.Spawns, spawn => spawn.MaterialVariant.ToString(CultureInfo.InvariantCulture));
            plan.CollisionObjectCount = Count(plan.Spawns, spawn => spawn.HasCollision);
            plan.LODLevelCount = Max(plan.Spawns, spawn => spawn.LODLevels);
            plan.SpawnMetadataHash = Hash(CanonicalSpawns(plan.Spawns));
            plan.ContentHash = Hash($"{plan.Variant}|{plan.WorldTileX}|{plan.WorldTileZ}|{plan.ObjectCount}|{plan.GeometryVariantCount}|{plan.MaterialVariantCount}|{plan.CollisionObjectCount}|{plan.LODLevelCount}|{plan.SpawnMetadataHash}");
            plan.SceneHash = Hash($"Scene|{plan.AssetPath}|{plan.ContentHash}|{plan.SpawnMetadataHash}");
            if (variant == Test_WorldFixtureVariant.Empty)
                plan.IsNavigable = false;
            plans.Add(plan);
        }

        private static void AddRandomObjects(
            ICollection<Test_WorldFixtureSpawn> spawns,
            Test_WorldFixturePlan plan,
            Test_WorldFixtureRandom random,
            int count,
            string kind,
            bool hasCollision)
        {
            for (var index = 0; index < count; index++)
            {
                var x = plan.BoundsMinX + 8d + random.NextDouble() * 240d;
                var z = plan.BoundsMinZ + 8d + random.NextDouble() * 240d;
                var primitive = kind == "Tree" ? (index % 2 == 0 ? "Cylinder" : "Capsule") : (index % 3 == 0 ? "Cube" : "Cylinder");
                var scale = kind == "Tree"
                    ? new Vector3(1.5f + (float)random.NextDouble() * 2f, 4f + (float)random.NextDouble() * 5f, 1.5f + (float)random.NextDouble() * 2f)
                    : new Vector3(1f + (float)random.NextDouble() * 4f, 1f + (float)random.NextDouble() * 5f, 1f + (float)random.NextDouble() * 4f);
                var lodLevels = kind == "Undergrowth" ? 2 : 3;
                AddSpawn(spawns, plan, index, kind, primitive, x, scale.y * 0.5d, z, scale, index % 4, lodLevels, hasCollision);
            }
        }

        private static void AddBoundaryObjects(
            ICollection<Test_WorldFixtureSpawn> spawns,
            Test_WorldFixturePlan plan,
            Test_WorldFixtureRandom random,
            int count)
        {
            for (var index = 0; index < count; index++)
            {
                var edgeOffset = 16d + (index + 1) * (224d / (count + 1));
                var x = plan.WorldTileX == 0 ? plan.BoundsMaxX - 8d : plan.BoundsMinX + 8d;
                var z = plan.BoundsMinZ + edgeOffset;
                AddSpawn(spawns, plan, index, "BoundaryProp", index % 2 == 0 ? "Cube" : "Cylinder", x, 0d, z, new Vector3(2f, 2f, 2f), index % 4, 1, true);
            }
        }

        private static void AddSpawn(
            ICollection<Test_WorldFixtureSpawn> spawns,
            Test_WorldFixturePlan plan,
            int index,
            string kind,
            string primitive,
            double x,
            double y,
            double z,
            Vector3 scale,
            int materialVariant,
            int lodLevels,
            bool hasCollision)
        {
            spawns.Add(new Test_WorldFixtureSpawn
            {
                SpawnID = $"{plan.FixtureID}/{kind.ToLowerInvariant()}/{index:D4}",
                Kind = kind,
                Primitive = primitive,
                WorldX = x,
                WorldY = y,
                WorldZ = z,
                ScaleX = scale.x,
                ScaleY = scale.y,
                ScaleZ = scale.z,
                OriginCellX = (int)Math.Floor(x / ORIGIN_CELL_SIZE_METERS),
                OriginCellZ = (int)Math.Floor(z / ORIGIN_CELL_SIZE_METERS),
                WorldTileX = (int)Math.Floor(x / WORLD_TILE_SIZE_METERS),
                WorldTileZ = (int)Math.Floor(z / WORLD_TILE_SIZE_METERS),
                MaterialVariant = materialVariant,
                LODLevels = lodLevels,
                HasCollision = hasCollision,
            });
        }

        private static string CanonicalSpawns(IReadOnlyList<Test_WorldFixtureSpawn> spawns)
        {
            // Quantize numeric metadata before hashing so Unity/Mono and .NET agree despite float rounding.
            var builder = new StringBuilder();
            foreach (var spawn in spawns)
            {
                builder.Append(spawn.SpawnID).Append('|')
                    .Append(spawn.Kind).Append('|')
                    .Append(spawn.Primitive).Append('|')
                    .Append(CanonicalDouble(spawn.WorldX)).Append('|')
                    .Append(CanonicalDouble(spawn.WorldY)).Append('|')
                    .Append(CanonicalDouble(spawn.WorldZ)).Append('|')
                    .Append(CanonicalFloat(spawn.ScaleX)).Append('|')
                    .Append(CanonicalFloat(spawn.ScaleY)).Append('|')
                    .Append(CanonicalFloat(spawn.ScaleZ)).Append('|')
                    .Append(spawn.OriginCellX).Append('|')
                    .Append(spawn.OriginCellZ).Append('|')
                    .Append(spawn.WorldTileX).Append('|')
                    .Append(spawn.WorldTileZ).Append('|')
                    .Append(spawn.MaterialVariant).Append('|')
                    .Append(spawn.LODLevels).Append('|')
                    .Append(spawn.HasCollision ? '1' : '0').Append(';');
            }
            return builder.ToString();
        }

        private static string CanonicalFloat(float value)
        {
            return CanonicalScaledValue(value);
        }

        private static string CanonicalDouble(double value)
        {
            return CanonicalScaledValue(value);
        }

        private static string CanonicalScaledValue(double value)
        {
            const double scale = 100d;
            var scaledValue = (long)Math.Round(value * scale, MidpointRounding.AwayFromZero);
            return scaledValue.ToString(CultureInfo.InvariantCulture);
        }

        private static int GetOutdoorCount(Test_WorldFixtureDensityTier tier)
        {
            switch (tier)
            {
                case Test_WorldFixtureDensityTier.D0_Minimal:
                    return 8;
                case Test_WorldFixtureDensityTier.D1_Default:
                    return 32;
                case Test_WorldFixtureDensityTier.D2_Dense:
                    return 64;
                case Test_WorldFixtureDensityTier.D3_Stress:
                    return 128;
                default:
                    throw new ArgumentOutOfRangeException(nameof(tier), tier, null);
            }
        }

        private static int GetTileCount(Test_WorldFixtureDensityTier tier) => GetOutdoorCount(tier) / 2;
        private static int GetForestTreeCount(Test_WorldFixtureDensityTier tier)
        {
            switch (tier)
            {
                case Test_WorldFixtureDensityTier.D0_Minimal:
                    return 12;
                case Test_WorldFixtureDensityTier.D1_Default:
                    return 50;
                case Test_WorldFixtureDensityTier.D2_Dense:
                    return 100;
                case Test_WorldFixtureDensityTier.D3_Stress:
                    return 200;
                default:
                    throw new ArgumentOutOfRangeException(nameof(tier), tier, null);
            }
        }

        private static int GetForestUndergrowthCount(Test_WorldFixtureDensityTier tier)
        {
            switch (tier)
            {
                case Test_WorldFixtureDensityTier.D0_Minimal:
                    return 24;
                case Test_WorldFixtureDensityTier.D1_Default:
                    return 200;
                case Test_WorldFixtureDensityTier.D2_Dense:
                    return 400;
                case Test_WorldFixtureDensityTier.D3_Stress:
                    return 800;
                default:
                    throw new ArgumentOutOfRangeException(nameof(tier), tier, null);
            }
        }

        private static int GetSettlementBuildingCount(Test_WorldFixtureDensityTier tier)
        {
            switch (tier)
            {
                case Test_WorldFixtureDensityTier.D0_Minimal:
                    return 4;
                case Test_WorldFixtureDensityTier.D1_Default:
                    return 15;
                case Test_WorldFixtureDensityTier.D2_Dense:
                    return 30;
                case Test_WorldFixtureDensityTier.D3_Stress:
                    return 60;
                default:
                    throw new ArgumentOutOfRangeException(nameof(tier), tier, null);
            }
        }

        private static int GetSettlementPropCount(Test_WorldFixtureDensityTier tier)
        {
            switch (tier)
            {
                case Test_WorldFixtureDensityTier.D0_Minimal:
                    return 12;
                case Test_WorldFixtureDensityTier.D1_Default:
                    return 80;
                case Test_WorldFixtureDensityTier.D2_Dense:
                    return 160;
                case Test_WorldFixtureDensityTier.D3_Stress:
                    return 320;
                default:
                    throw new ArgumentOutOfRangeException(nameof(tier), tier, null);
            }
        }

        private static int CountDistinct<T>(IEnumerable<Test_WorldFixtureSpawn> spawns, Func<Test_WorldFixtureSpawn, T> selector)
        {
            var values = new HashSet<T>();
            foreach (var spawn in spawns)
                values.Add(selector(spawn));
            return values.Count;
        }

        private static int Count(IEnumerable<Test_WorldFixtureSpawn> spawns, Func<Test_WorldFixtureSpawn, bool> predicate)
        {
            var count = 0;
            foreach (var spawn in spawns)
                if (predicate(spawn))
                    count++;
            return count;
        }

        private static int Max(IEnumerable<Test_WorldFixtureSpawn> spawns, Func<Test_WorldFixtureSpawn, int> selector)
        {
            var max = 0;
            foreach (var spawn in spawns)
                max = Math.Max(max, selector(spawn));
            return max;
        }
    }

    /// <summary>
    /// Versioned deterministic PRNG for world fixture input data.
    /// It follows the benchmark contract's SHA-256 little-endian seed derivation and does not
    /// depend on process-randomised hashes or runtime-specific <see cref="System.Random"/> behaviour.
    /// </summary>
    internal sealed class Test_WorldFixtureRandom
    {
        private uint _state;

        public Test_WorldFixtureRandom(int replicateSeed, string streamName, int sceneIndex)
        {
            var seedText = $"ninthage-bench-seed-v1\nworld-fixtures\n{Test_WorldFixtureLayout.FIXTURE_VERSION}\n{replicateSeed}\n{streamName}:{sceneIndex}";
            using (var sha256 = SHA256.Create())
            {
                var digest = sha256.ComputeHash(Encoding.UTF8.GetBytes(seedText));
                _state = (uint)(digest[0] | digest[1] << 8 | digest[2] << 16 | digest[3] << 24);
            }

            if (_state == 0)
                _state = 0x6D2B79F5u;
        }

        public double NextDouble()
        {
            _state ^= _state << 13;
            _state ^= _state >> 17;
            _state ^= _state << 5;
            return _state / 4294967296d;
        }
    }
}
